from pathlib import Path
ROOT = Path(__file__).resolve().parent.parent
DOCS = ROOT/"docs"

def am(dec):
    if dec>=2: return f"+{round((dec-1)*100)}"
    return f"-{round(100/(dec-1))}" if dec>1 else "—"

# each: sport slug, name, olbg note, picks list dicts
# prob = our estimated win probability %; fair decimal computed =100/prob
SPORTS = []
def S(slug,name,competition,window,olbg,picks):
    SPORTS.append(dict(slug=slug,name=name,competition=competition,window=window,olbg=olbg,picks=picks))
def P(date,event,market,pick,prob,conf,pred,src,srcurl,*args):
    flag=args[-1] if args else ""
    dec = round(100/prob,2) if prob else None
    return dict(date=date,event=event,market=market,pick=pick,prob=prob,dec=dec,american=am(dec) if dec else "—",conf=conf,pred=pred,src=src,srcurl=srcurl,flag=flag)

